		// dark panel). Real DSH defines every alias var, so fallback is a safety net.
		const RAIL = 'var(--dsw-alias-border-l3, rgba(127,127,127,.4))';
		const INK = 'var(--dsw-alias-label-primary, light-dark(#0f1115, #f9fafb))';
